    chk(hwo.irq_sta === 32'h00F000A0, "hwo irq_sta");
    apb_wr('h0100, 32'hFFFFFFFF);
    apb_wr('h0104, 32'h0);
    rdchk('h0108, 32'h0, "irq sta clr");

    // P5: One pulse for a write of 1; no pulse for a write of 0.
    pc = cnt_glb_ctrl_srst;
    apb_wr('h000C, 32'h00000001);
    repeat (3) @(posedge pclk);
    chk(cnt_glb_ctrl_srst === pc + 1, "pulse1 GLB[0].CTRL");
    apb_wr('h000C, 32'h0);
    repeat (3) @(posedge pclk);
    chk(cnt_glb_ctrl_srst === pc + 1, "pulse0 GLB[0].CTRL");
    pc = cnt_sys_ts_ctrl_clr;
    apb_wr('h0208, 32'h00000100);
    repeat (3) @(posedge pclk);
    chk(cnt_sys_ts_ctrl_clr === pc + 1, "pulse1 SYS[0].TS_CTRL");
    apb_wr('h0208, 32'h0);
    repeat (3) @(posedge pclk);
    chk(cnt_sys_ts_ctrl_clr === pc + 1, "pulse0 SYS[0].TS_CTRL");
    pc = cnt_spi_db_go[0];
    apb_wr('h0418, 32'h00000001);
    repeat (3) @(posedge pclk);
    chk(cnt_spi_db_go[0] === pc + 1, "pulse1 SPI[0].DB");
    apb_wr('h0418, 32'h0);
    repeat (3) @(posedge pclk);
    chk(cnt_spi_db_go[0] === pc + 1, "pulse0 SPI[0].DB");
    pc = cnt_spi_db_go[1];
    apb_wr('h0498, 32'h00000001);
    repeat (3) @(posedge pclk);
    chk(cnt_spi_db_go[1] === pc + 1, "pulse1 SPI[1].DB");
    apb_wr('h0498, 32'h0);
    repeat (3) @(posedge pclk);
    chk(cnt_spi_db_go[1] === pc + 1, "pulse0 SPI[1].DB");
    pc = cnt_spi_db_go[2];
    apb_wr('h0518, 32'h00000001);
    repeat (3) @(posedge pclk);
    chk(cnt_spi_db_go[2] === pc + 1, "pulse1 SPI[2].DB");
    apb_wr('h0518, 32'h0);
    repeat (3) @(posedge pclk);
    chk(cnt_spi_db_go[2] === pc + 1, "pulse0 SPI[2].DB");
    pc = cnt_spi_db_go[3];
    apb_wr('h0598, 32'h00000001);
    repeat (3) @(posedge pclk);
    chk(cnt_spi_db_go[3] === pc + 1, "pulse1 SPI[3].DB");
    apb_wr('h0598, 32'h0);
    repeat (3) @(posedge pclk);
    chk(cnt_spi_db_go[3] === pc + 1, "pulse0 SPI[3].DB");
    pc = cnt_spi_db_go[4];
    apb_wr('h0618, 32'h00000001);
    repeat (3) @(posedge pclk);
    chk(cnt_spi_db_go[4] === pc + 1, "pulse1 SPI[4].DB");
    apb_wr('h0618, 32'h0);
    repeat (3) @(posedge pclk);
    chk(cnt_spi_db_go[4] === pc + 1, "pulse0 SPI[4].DB");
    pc = cnt_spi_db_go[5];
    apb_wr('h0698, 32'h00000001);
    repeat (3) @(posedge pclk);
    chk(cnt_spi_db_go[5] === pc + 1, "pulse1 SPI[5].DB");
    apb_wr('h0698, 32'h0);
    repeat (3) @(posedge pclk);
    chk(cnt_spi_db_go[5] === pc + 1, "pulse0 SPI[5].DB");
    pc = cnt_spi_db_go[6];
    apb_wr('h0718, 32'h00000001);
    repeat (3) @(posedge pclk);
    chk(cnt_spi_db_go[6] === pc + 1, "pulse1 SPI[6].DB");
    apb_wr('h0718, 32'h0);
    repeat (3) @(posedge pclk);
    chk(cnt_spi_db_go[6] === pc + 1, "pulse0 SPI[6].DB");
    pc = cnt_spi_db_go[7];
    apb_wr('h0798, 32'h00000001);
    repeat (3) @(posedge pclk);
    chk(cnt_spi_db_go[7] === pc + 1, "pulse1 SPI[7].DB");
    apb_wr('h0798, 32'h0);
    repeat (3) @(posedge pclk);
    chk(cnt_spi_db_go[7] === pc + 1, "pulse0 SPI[7].DB");
    pc = cnt_boot_db_go;
    apb_wr('h0814, 32'h00000001);
    repeat (3) @(posedge pclk);
    chk(cnt_boot_db_go === pc + 1, "pulse1 BOOT[0].DB");
    apb_wr('h0814, 32'h0);
    repeat (3) @(posedge pclk);
    chk(cnt_boot_db_go === pc + 1, "pulse0 BOOT[0].DB");
    pc = cnt_send_db_go;
    apb_wr('h0C0C, 32'h00000001);
    repeat (3) @(posedge pclk);
    chk(cnt_send_db_go === pc + 1, "pulse1 SEND[0].DB");
    apb_wr('h0C0C, 32'h0);
    repeat (3) @(posedge pclk);
    chk(cnt_send_db_go === pc + 1, "pulse0 SEND[0].DB");
    pc = cnt_cc_db_go;
    apb_wr('h380C, 32'h00000001);
    repeat (3) @(posedge pclk);
    chk(cnt_cc_db_go === pc + 1, "pulse1 CC[0].DB");
    apb_wr('h380C, 32'h0);
    repeat (3) @(posedge pclk);
    chk(cnt_cc_db_go === pc + 1, "pulse0 CC[0].DB");

    // P6: Read each RO hardware field with the other inputs held at zero.
    hwi.glb_sta_spi_busy = 8'hFF;
    #1;
    rdchk('h0010, 32'h000000FF, "ro-hw GLB[0].STA.SPI_BUSY");
    hwi.glb_sta_spi_busy = '0;
    hwi.glb_sta_boot_busy = 1'h1;
    #1;
    rdchk('h0010, 32'h00000100, "ro-hw GLB[0].STA.BOOT_BUSY");
    hwi.glb_sta_boot_busy = '0;
    hwi.glb_sta_send_busy = 1'h1;
    #1;
    rdchk('h0010, 32'h00000200, "ro-hw GLB[0].STA.SEND_BUSY");
    hwi.glb_sta_send_busy = '0;
    hwi.glb_sta_cc_busy = 1'h1;
    #1;
    rdchk('h0010, 32'h00000400, "ro-hw GLB[0].STA.CC_BUSY");
    hwi.glb_sta_cc_busy = '0;
    hwi.sys_ts_lo = 32'hFFFFFFFF;
    #1;
    rdchk('h020C, 32'hFFFFFFFF, "ro-hw SYS[0].TS_LO");
    hwi.sys_ts_lo = '0;
    hwi.sys_ts_hi = 16'hFFFF;
    #1;
    rdchk('h0210, 32'h0000FFFF, "ro-hw SYS[0].TS_HI");
    hwi.sys_ts_hi = '0;
    hwi.spi_rdata[0] = 32'hFFFFFFFF;
    #1;
    rdchk('h040C, 32'hFFFFFFFF, "ro-hw SPI[0].RDATA");
    hwi.spi_rdata[0] = '0;
    hwi.spi_rdata[1] = 32'hFFFFFFFF;
    #1;
    rdchk('h048C, 32'hFFFFFFFF, "ro-hw SPI[1].RDATA");
    hwi.spi_rdata[1] = '0;
    hwi.spi_rdata[2] = 32'hFFFFFFFF;
    #1;
    rdchk('h050C, 32'hFFFFFFFF, "ro-hw SPI[2].RDATA");
    hwi.spi_rdata[2] = '0;
    hwi.spi_rdata[3] = 32'hFFFFFFFF;
    #1;
    rdchk('h058C, 32'hFFFFFFFF, "ro-hw SPI[3].RDATA");
    hwi.spi_rdata[3] = '0;
    hwi.spi_rdata[4] = 32'hFFFFFFFF;
    #1;
    rdchk('h060C, 32'hFFFFFFFF, "ro-hw SPI[4].RDATA");
    hwi.spi_rdata[4] = '0;
    hwi.spi_rdata[5] = 32'hFFFFFFFF;
    #1;
    rdchk('h068C, 32'hFFFFFFFF, "ro-hw SPI[5].RDATA");
    hwi.spi_rdata[5] = '0;
    hwi.spi_rdata[6] = 32'hFFFFFFFF;
    #1;
    rdchk('h070C, 32'hFFFFFFFF, "ro-hw SPI[6].RDATA");
    hwi.spi_rdata[6] = '0;
    hwi.spi_rdata[7] = 32'hFFFFFFFF;
    #1;
    rdchk('h078C, 32'hFFFFFFFF, "ro-hw SPI[7].RDATA");
    hwi.spi_rdata[7] = '0;
    hwi.spi_sta_busy[0] = 1'h1;
    #1;
    rdchk('h041C, 32'h00000001, "ro-hw SPI[0].STA.BUSY");
    hwi.spi_sta_busy[0] = '0;
    hwi.spi_sta_busy[1] = 1'h1;
    #1;
    rdchk('h049C, 32'h00000001, "ro-hw SPI[1].STA.BUSY");
    hwi.spi_sta_busy[1] = '0;
    hwi.spi_sta_busy[2] = 1'h1;
    #1;
    rdchk('h051C, 32'h00000001, "ro-hw SPI[2].STA.BUSY");
    hwi.spi_sta_busy[2] = '0;
    hwi.spi_sta_busy[3] = 1'h1;
    #1;
    rdchk('h059C, 32'h00000001, "ro-hw SPI[3].STA.BUSY");
    hwi.spi_sta_busy[3] = '0;
    hwi.spi_sta_busy[4] = 1'h1;
    #1;
    rdchk('h061C, 32'h00000001, "ro-hw SPI[4].STA.BUSY");
    hwi.spi_sta_busy[4] = '0;
    hwi.spi_sta_busy[5] = 1'h1;
    #1;
    rdchk('h069C, 32'h00000001, "ro-hw SPI[5].STA.BUSY");
    hwi.spi_sta_busy[5] = '0;
    hwi.spi_sta_busy[6] = 1'h1;
    #1;
    rdchk('h071C, 32'h00000001, "ro-hw SPI[6].STA.BUSY");
    hwi.spi_sta_busy[6] = '0;
    hwi.spi_sta_busy[7] = 1'h1;
    #1;
    rdchk('h079C, 32'h00000001, "ro-hw SPI[7].STA.BUSY");
    hwi.spi_sta_busy[7] = '0;
    hwi.boot_sta_busy = 1'h1;
    #1;
    rdchk('h0818, 32'h00000001, "ro-hw BOOT[0].STA.BUSY");
    hwi.boot_sta_busy = '0;
    hwi.boot_sta_err_code = 4'hF;
    #1;
    rdchk('h0818, 32'h0000F000, "ro-hw BOOT[0].STA.ERR_CODE");
    hwi.boot_sta_err_code = '0;
    hwi.send_sta_busy = 1'h1;
    #1;
    rdchk('h0C10, 32'h00000001, "ro-hw SEND[0].STA.BUSY");
    hwi.send_sta_busy = '0;
    hwi.send_sent = 32'hFFFFFFFF;
    #1;
    rdchk('h0C14, 32'hFFFFFFFF, "ro-hw SEND[0].SENT");
    hwi.send_sent = '0;
    hwi.recv_sta_level[0] = 16'hFFFF;
    #1;
    rdchk('h1014, 32'hFFFF0000, "ro-hw RECV[0].STA.LEVEL");
    hwi.recv_sta_level[0] = '0;
    hwi.recv_sta_level[1] = 16'hFFFF;
    #1;
    rdchk('h1054, 32'hFFFF0000, "ro-hw RECV[1].STA.LEVEL");
    hwi.recv_sta_level[1] = '0;
    hwi.recv_sta_level[2] = 16'hFFFF;
    #1;
    rdchk('h1094, 32'hFFFF0000, "ro-hw RECV[2].STA.LEVEL");
    hwi.recv_sta_level[2] = '0;
    hwi.recv_wptr[0] = 32'hFFFFFFFF;
    #1;
    rdchk('h1018, 32'hFFFFFFFF, "ro-hw RECV[0].WPTR");
    hwi.recv_wptr[0] = '0;
    hwi.recv_wptr[1] = 32'hFFFFFFFF;
    #1;
    rdchk('h1058, 32'hFFFFFFFF, "ro-hw RECV[1].WPTR");
    hwi.recv_wptr[1] = '0;
    hwi.recv_wptr[2] = 32'hFFFFFFFF;
    #1;
    rdchk('h1098, 32'hFFFFFFFF, "ro-hw RECV[2].WPTR");
    hwi.recv_wptr[2] = '0;
    hwi.cc_rdata = 32'hFFFFFFFF;
    #1;
    rdchk('h3808, 32'hFFFFFFFF, "ro-hw CC[0].RDATA");
    hwi.cc_rdata = '0;
    hwi.cc_sta_busy = 1'h1;
    #1;
    rdchk('h3810, 32'h00000001, "ro-hw CC[0].STA.BUSY");
    hwi.cc_sta_busy = '0;
    hwi.spiwin_sta_busy = 1'h1;
    #1;
    rdchk('h3C0C, 32'h00000001, "ro-hw SPIWIN[0].STA.BUSY");
    hwi.spiwin_sta_busy = '0;

    // P7: Unmapped and reserved addresses return PSLVERR and read as zero.
    apb_rd('h0014, rd);
    chk(last_err && rd === 32'h0, "hole rd 0x0014");
    apb_wr('h0014, 32'hDEADBEEF);
    chk(last_err, "hole wr 0x0014");
    apb_rd('h0440, rd);
    chk(last_err && rd === 32'h0, "hole rd 0x0440");
    apb_wr('h0440, 32'hDEADBEEF);
    chk(last_err, "hole wr 0x0440");
    apb_rd('h04C0, rd);
    chk(last_err && rd === 32'h0, "hole rd 0x04C0");
    apb_wr('h04C0, 32'hDEADBEEF);
    chk(last_err, "hole wr 0x04C0");
    apb_rd('h0940, rd);
    chk(last_err && rd === 32'h0, "hole rd 0x0940");
    apb_wr('h0940, 32'hDEADBEEF);
    chk(last_err, "hole wr 0x0940");
    apb_rd('h1300, rd);
    chk(last_err && rd === 32'h0, "hole rd 0x1300");
    apb_wr('h1300, 32'hDEADBEEF);
    chk(last_err, "hole wr 0x1300");
    apb_rd('h2800, rd);
    chk(last_err && rd === 32'h0, "hole rd 0x2800");
    apb_wr('h2800, 32'hDEADBEEF);
    chk(last_err, "hole wr 0x2800");
    apb_rd('h3900, rd);
    chk(last_err && rd === 32'h0, "hole rd 0x3900");
    apb_wr('h3900, 32'hDEADBEEF);
    chk(last_err, "hole wr 0x3900");
    apb_rd('h7FFC, rd);
    chk(last_err && rd === 32'h0, "hole rd 0x7FFC");
    apb_wr('h7FFC, 32'hDEADBEEF);
    chk(last_err, "hole wr 0x7FFC");
    apb_rd('hFFFC, rd);
    chk(last_err && rd === 32'h0, "hole rd 0xFFFC");
    apb_wr('hFFFC, 32'hDEADBEEF);
    chk(last_err, "hole wr 0xFFFC");

    // P8: Array instances retain independent register values.
    apb_wr('h0404, 32'h11111111);
    apb_wr('h0484, 32'h22222222);
    apb_wr('h0504, 32'h33333333);
    apb_wr('h0584, 32'h44444444);
    apb_wr('h0604, 32'h55555555);
    apb_wr('h0684, 32'h66666666);
    apb_wr('h0704, 32'h77777777);
    apb_wr('h0784, 32'h88888888);
    rdchk('h0404, 32'h11111111, "alias SPI[0].ADDR");
    rdchk('h0484, 32'h22222222, "alias SPI[1].ADDR");
    rdchk('h0504, 32'h33333333, "alias SPI[2].ADDR");
    rdchk('h0584, 32'h44444444, "alias SPI[3].ADDR");
    rdchk('h0604, 32'h55555555, "alias SPI[4].ADDR");
    rdchk('h0684, 32'h66666666, "alias SPI[5].ADDR");
    rdchk('h0704, 32'h77777777, "alias SPI[6].ADDR");
    rdchk('h0784, 32'h88888888, "alias SPI[7].ADDR");
    apb_wr('h1000, 32'h11111111);
    apb_wr('h1040, 32'h22222222);
    apb_wr('h1080, 32'h33333333);
    rdchk('h1000, 32'h11111111, "alias RECV[0].RING_LO");
    rdchk('h1040, 32'h22222222, "alias RECV[1].RING_LO");
    rdchk('h1080, 32'h33333333, "alias RECV[2].RING_LO");

    if (errs == 0) $display("CSR TB PASS (%0d checks)", checks);
    else           $display("CSR TB FAIL (%0d/%0d checks failed)", errs, checks);
    $finish;
  end

  initial begin #10ms; $display("CSR TB TIMEOUT"); $finish; end

endmodule
